package com.lianxibu.site.service.content;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.util.*;
import org.junit.jupiter.api.Test;
class OperationAffectedReadServiceTest {
 private final Actor owner=new Actor("fictional-owner","owner");
 private static OperationAffectedReadService.Ref ref(int i){return new OperationAffectedReadService.Ref("content","fictional-"+String.format("%03d",i),null);}
 private static OperationAffectedReadService.Snapshot complete(String id,List<OperationAffectedReadService.Ref> refs){return new OperationAffectedReadService.Snapshot(id,true,refs);}
 private static byte[] key(){byte[] bytes=new byte[32];Arrays.fill(bytes,(byte)7);return bytes;}
 @Test void completeFrozenSetSortedDeduplicatedAndOpaquePagesSurviveReaderRestart(){var refs=new ArrayList<OperationAffectedReadService.Ref>();for(int i=51;i>=1;i--)refs.add(ref(i));refs.add(ref(1));var proof=complete("fictional-operation",refs);var service=new OperationAffectedReadService(id->proof,key());var page=service.read(owner,"fictional-operation",null,20);assertEquals(51,page.total());assertEquals(ref(1),page.items().getFirst());assertEquals(20,page.items().size());assertNotNull(page.nextCursor());assertFalse(page.nextCursor().contains("fictional"));var next=new OperationAffectedReadService(id->proof,key()).read(owner,"fictional-operation",page.nextCursor(),20);assertEquals(ref(21),next.items().getFirst());var last=service.read(owner,"fictional-operation",next.nextCursor(),20);assertEquals(11,last.items().size());assertNull(last.nextCursor());assertThrows(UnsupportedOperationException.class,()->page.items().clear());}
 @Test void pendingIsUnknownAndCompleteZeroIsKnown(){var pending=new OperationAffectedReadService(id->new OperationAffectedReadService.Snapshot(id,false,List.of()),key());var p=pending.read(owner,"fictional-operation",null,20);assertEquals("pending",p.state());assertNull(p.total());assertNull(p.nextCursor());assertTrue(p.items().isEmpty());assertThrows(IllegalArgumentException.class,()->pending.read(owner,"fictional-operation","fictional-cursor",20));var zero=new OperationAffectedReadService(id->complete(id,List.of()),key()).read(owner,"fictional-operation",null,20);assertEquals("complete",zero.state());assertEquals(0,zero.total());}
 @Test void cursorRejectsOtherOperationLimitSnapshotAndTampering(){var proof=complete("fictional-operation",List.of(ref(1),ref(2),ref(3)));var service=new OperationAffectedReadService(id->complete(id,proof.resources()),key());String cursor=service.read(owner,"fictional-operation",null,1).nextCursor();assertThrows(OperationAffectedReadService.CursorConflict.class,()->service.read(owner,"fictional-other",cursor,1));assertThrows(OperationAffectedReadService.CursorConflict.class,()->service.read(owner,"fictional-operation",cursor,2));var changed=new OperationAffectedReadService(id->complete(id,List.of(ref(1),ref(2))),key());assertThrows(OperationAffectedReadService.CursorConflict.class,()->changed.read(owner,"fictional-operation",cursor,1));assertThrows(IllegalArgumentException.class,()->service.read(owner,"fictional-operation","!"+cursor,1));}
 @Test void deniedBeforeStoreLookupAndMissingSeparateFromUnproven(){int[] calls={0};var service=new OperationAffectedReadService(id->{calls[0]++;return null;},key());assertThrows(OperationAffectedReadService.Denied.class,()->service.read(null,"fictional-operation",null,20));assertThrows(OperationAffectedReadService.Denied.class,()->service.read(new Actor("fictional-user","user"),"fictional-operation",null,20));assertEquals(0,calls[0]);assertThrows(OperationAffectedReadService.Missing.class,()->service.read(owner,"fictional-operation",null,20));}
 @Test void impossibleDurableProofFailsClosed(){for(var proof:List.of(complete("fictional-other",List.of()),new OperationAffectedReadService.Snapshot("fictional-operation",false,List.of(ref(1))),complete("fictional-operation",List.of(new OperationAffectedReadService.Ref("", "fictional-id",null))))){var service=new OperationAffectedReadService(id->proof,key());assertThrows(IllegalStateException.class,()->service.read(owner,"fictional-operation",null,20));}}
}
